// JSON Schema subset validator and the compiled-in library schemas (see schema.h).
#include "schema.h"

#include <cstddef>
#include <exception>
#include <map>
#include <mutex>
#include <optional>
#include <regex>
#include <set>
#include <string>
#include <utility>

namespace ray::lib::detail {

// Generated by src/lib/CMakeLists.txt from schemas/*.schema.json.
struct EmbeddedFile {
    const char* name;
    const unsigned char* data;
    std::size_t size;
};
extern const EmbeddedFile kEmbeddedSchemas[];
extern const std::size_t kEmbeddedSchemaCount;

namespace {

using json::Value;

constexpr const char* kTypeMismatch = "schema: type mismatch";

const std::set<std::string_view>& knownKeywords()
{
    static const std::set<std::string_view> keywords = {"type",
                                                        "enum",
                                                        "const",
                                                        "minimum",
                                                        "maximum",
                                                        "exclusiveMinimum",
                                                        "exclusiveMaximum",
                                                        "minLength",
                                                        "maxLength",
                                                        "pattern",
                                                        "minItems",
                                                        "maxItems",
                                                        "items",
                                                        "required",
                                                        "properties",
                                                        "additionalProperties",
                                                        "anyOf",
                                                        "oneOf",
                                                        "$ref",
                                                        "$schema",
                                                        "$id",
                                                        "$defs",
                                                        "$comment",
                                                        "title",
                                                        "description",
                                                        "default",
                                                        "examples"};
    return keywords;
}

tl::unexpected<Error> problem(const std::string& path, const std::string& what)
{
    return tl::unexpected<Error>(
        Error{ErrorCode::FormatError, (path.empty() ? std::string("/") : path) + ": " + what, {}});
}

std::string pointerAppend(const std::string& base, std::string_view token)
{
    std::string out = base;
    out += '/';
    for (const char c : token) {
        if (c == '~') {
            out += "~0";
        } else if (c == '/') {
            out += "~1";
        } else {
            out += c;
        }
    }
    return out;
}

std::size_t codePoints(const std::string& s)
{
    std::size_t n = 0;
    for (const char c : s) {
        if ((static_cast<unsigned char>(c) & 0xC0) != 0x80) {
            ++n;
        }
    }
    return n;
}

bool isInteger(const Value& v)
{
    if (!v.isNumber()) {
        return false;
    }
    const double d = v.asNumber();
    return d >= -9.0e15 && d <= 9.0e15 && static_cast<double>(static_cast<long long>(d)) == d;
}

bool typeMatches(std::string_view name, const Value& v)
{
    if (name == "integer") {
        return isInteger(v);
    }
    if (name == "number") {
        return v.isNumber();
    }
    if (name == "null") {
        return v.isNull();
    }
    if (name == "boolean") {
        return v.isBool();
    }
    if (name == "string") {
        return v.isString();
    }
    if (name == "array") {
        return v.isArray();
    }
    if (name == "object") {
        return v.isObject();
    }
    return false;
}

const char* typeName(const Value& v)
{
    switch (v.type()) {
    case Value::Type::Null:
        return "null";
    case Value::Type::Bool:
        return "a boolean";
    case Value::Type::Number:
        return "a number";
    case Value::Type::String:
        return "a string";
    case Value::Type::Array:
        return "an array";
    case Value::Type::Object:
        return "an object";
    }
    return "a value";
}

std::string shortText(const Value& v)
{
    std::string text = json::write(v);
    if (text.size() > 60) {
        text = text.substr(0, 57) + "...";
    }
    return text;
}

} // namespace

bool jsonEqual(const Value& a, const Value& b)
{
    if (a.type() != b.type()) {
        return false;
    }
    switch (a.type()) {
    case Value::Type::Null:
        return true;
    case Value::Type::Bool:
        return a.asBool() == b.asBool();
    case Value::Type::Number:
        return a.asNumber() == b.asNumber();
    case Value::Type::String:
        return a.asString() == b.asString();
    case Value::Type::Array: {
        const auto& x = a.asArray();
        const auto& y = b.asArray();
        if (x.size() != y.size()) {
            return false;
        }
        for (std::size_t i = 0; i < x.size(); ++i) {
            if (!jsonEqual(x[i], y[i])) {
                return false;
            }
        }
        return true;
    }
    case Value::Type::Object: {
        const auto& x = a.asObject();
        const auto& y = b.asObject();
        if (x.size() != y.size()) {
            return false;
        }
        for (std::size_t i = 0; i < x.size(); ++i) {
            if (x[i].key != y[i].key || !jsonEqual(x[i].value, y[i].value)) {
                return false;
            }
        }
        return true;
    }
    }
    return false;
}

struct Schema::Impl {
    Value root;
    std::map<const Value*, std::regex> patterns; // looked up only, never iterated

    Status prepare(const Value& schema, const std::string& path, int depth);
    Status check(const Value& schema, const Value& v, const std::string& path, int depth) const;
    Status checkNumber(const Value& schema, const Value& v, const std::string& path) const;
    Status checkString(const Value& schema, const Value& v, const std::string& path) const;
    Status checkArray(const Value& schema, const Value& v, const std::string& path, int depth) const;
    Status checkObject(const Value& schema, const Value& v, const std::string& path, int depth) const;
    const Value* resolve(const Value& schema) const;
};

Status Schema::Impl::prepare(const Value& schema, const std::string& path, int depth)
{
    if (depth > 64) {
        return problem(path, "the schema is nested too deeply");
    }
    if (schema.isBool()) {
        return {};
    }
    if (!schema.isObject()) {
        return problem(path, "a schema must be an object or a boolean");
    }
    for (const json::Member& m : schema.asObject()) {
        if (knownKeywords().count(m.key) == 0) {
            return problem(path, "schema keyword '" + m.key + "' is not supported by src/lib/schema.cpp");
        }
    }
    if (const Value* p = schema.find("pattern")) {
        if (!p->isString()) {
            return problem(path, "pattern must be a string");
        }
        try {
            patterns.emplace(p, std::regex(p->asString(), std::regex::ECMAScript));
        } catch (const std::exception&) {
            return problem(path, "invalid pattern " + p->asString());
        }
    }
    if (const Value* r = schema.find("$ref")) {
        if (!r->isString() || r->asString().rfind("#/$defs/", 0) != 0 || resolve(schema) == nullptr) {
            return problem(path, "only references to this schema's $defs are supported");
        }
    }
    for (const char* key : {"properties", "$defs"}) {
        if (const Value* map = schema.find(key)) {
            if (!map->isObject()) {
                return problem(path, std::string(key) + " must be an object");
            }
            for (const json::Member& m : map->asObject()) {
                if (auto st = prepare(m.value, pointerAppend(pointerAppend(path, key), m.key), depth + 1); !st) {
                    return st;
                }
            }
        }
    }
    for (const char* key : {"items", "additionalProperties"}) {
        if (const Value* sub = schema.find(key)) {
            if (auto st = prepare(*sub, pointerAppend(path, key), depth + 1); !st) {
                return st;
            }
        }
    }
    for (const char* key : {"anyOf", "oneOf"}) {
        if (const Value* list = schema.find(key)) {
            if (!list->isArray() || list->asArray().empty()) {
                return problem(path, std::string(key) + " must be a non-empty array");
            }
            for (std::size_t i = 0; i < list->asArray().size(); ++i) {
                if (auto st = prepare(list->asArray()[i], pointerAppend(pointerAppend(path, key), std::to_string(i)),
                                      depth + 1);
                    !st) {
                    return st;
                }
            }
        }
    }
    return {};
}

const Value* Schema::Impl::resolve(const Value& schema) const
{
    const Value* r = schema.find("$ref");
    if (r == nullptr || !r->isString()) {
        return nullptr;
    }
    const Value* defs = root.find("$defs");
    return defs ? defs->find(std::string_view(r->asString()).substr(8)) : nullptr;
}

Status Schema::Impl::checkNumber(const Value& schema, const Value& v, const std::string& path) const
{
    const double d = v.asNumber();
    if (const Value* m = schema.find("minimum"); m && m->isNumber() && d < m->asNumber()) {
        return problem(path, "must be at least " + json::write(*m));
    }
    if (const Value* m = schema.find("maximum"); m && m->isNumber() && d > m->asNumber()) {
        return problem(path, "must be at most " + json::write(*m));
    }
    if (const Value* m = schema.find("exclusiveMinimum"); m && m->isNumber() && d <= m->asNumber()) {
        return problem(path, "must be greater than " + json::write(*m));
    }
    if (const Value* m = schema.find("exclusiveMaximum"); m && m->isNumber() && d >= m->asNumber()) {
        return problem(path, "must be less than " + json::write(*m));
    }
    return {};
}

Status Schema::Impl::checkString(const Value& schema, const Value& v, const std::string& path) const
{
    const std::string& s = v.asString();
    const std::size_t n = codePoints(s);
    if (const Value* m = schema.find("minLength"); m && m->isNumber() && static_cast<double>(n) < m->asNumber()) {
        return problem(path, m->asNumber() == 1 ? "must not be empty"
                                                : "must be at least " + json::write(*m) + " characters long");
    }
    if (const Value* m = schema.find("maxLength"); m && m->isNumber() && static_cast<double>(n) > m->asNumber()) {
        return problem(path, "must be at most " + json::write(*m) + " characters long");
    }
    if (const Value* p = schema.find("pattern")) {
        const auto it = patterns.find(p);
        if (it != patterns.end() && !std::regex_search(s, it->second)) {
            return problem(path, "\"" + s + "\" does not match the pattern " + p->asString());
        }
    }
    return {};
}

Status Schema::Impl::checkArray(const Value& schema, const Value& v, const std::string& path, int depth) const
{
    const auto& items = v.asArray();
    if (const Value* m = schema.find("minItems");
        m && m->isNumber() && static_cast<double>(items.size()) < m->asNumber()) {
        return problem(path, "must have at least " + json::write(*m) + " items");
    }
    if (const Value* m = schema.find("maxItems");
        m && m->isNumber() && static_cast<double>(items.size()) > m->asNumber()) {
        return problem(path, "must have at most " + json::write(*m) + " items");
    }
    if (const Value* itemSchema = schema.find("items")) {
        for (std::size_t i = 0; i < items.size(); ++i) {
            if (auto st = check(*itemSchema, items[i], pointerAppend(path, std::to_string(i)), depth + 1); !st) {
                return st;
            }
        }
    }
    return {};
}

Status Schema::Impl::checkObject(const Value& schema, const Value& v, const std::string& path, int depth) const
{
    if (const Value* required = schema.find("required"); required && required->isArray()) {
        for (const Value& name : required->asArray()) {
            if (name.isString() && !v.find(name.asString())) {
                return problem(pointerAppend(path, name.asString()), "is required");
            }
        }
    }
    const Value* properties = schema.find("properties");
    const Value* additional = schema.find("additionalProperties");
    for (const json::Member& member : v.asObject()) {
        const std::string memberPath = pointerAppend(path, member.key);
        const Value* own = properties ? properties->find(member.key) : nullptr;
        if (own) {
            if (auto st = check(*own, member.value, memberPath, depth + 1); !st) {
                return st;
            }
        } else if (additional) {
            if (auto st = check(*additional, member.value, memberPath, depth + 1); !st) {
                return st;
            }
        }
    }
    return {};
}

Status Schema::Impl::check(const Value& schema, const Value& v, const std::string& path, int depth) const
{
    if (depth > 64) {
        return problem(path, "is nested too deeply");
    }
    if (schema.isBool()) {
        return schema.asBool() ? Status{} : problem(path, "is not allowed here");
    }
    if (const Value* target = resolve(schema)) {
        if (auto st = check(*target, v, path, depth + 1); !st) {
            return st;
        }
    }
    if (const Value* type = schema.find("type")) {
        bool ok = false;
        std::string expected;
        if (type->isString()) {
            ok = typeMatches(type->asString(), v);
            expected = type->asString();
        } else if (type->isArray()) {
            for (const Value& t : type->asArray()) {
                if (t.isString()) {
                    ok = ok || typeMatches(t.asString(), v);
                    expected += (expected.empty() ? "" : " or ") + t.asString();
                }
            }
        }
        if (!ok) {
            const bool vowel =
                !expected.empty() && std::string_view("aeiou").find(expected[0]) != std::string_view::npos;
            std::string got = typeName(v);
            if (v.isNumber() && expected == "integer") {
                got = "a number with a fraction";
            }
            const std::string article = expected == "null" ? "" : (vowel ? "an " : "a ");
            auto mismatch = problem(path, "must be " + article + expected + ", not " + got);
            mismatch.value().context.push_back(kTypeMismatch);
            return mismatch;
        }
    }
    if (const Value* e = schema.find("enum"); e && e->isArray()) {
        bool found = false;
        std::string choices;
        for (const Value& option : e->asArray()) {
            found = found || jsonEqual(option, v);
            choices += (choices.empty() ? "" : ", ") + json::write(option);
        }
        if (!found) {
            return problem(path, "must be one of " + choices + ", not " + shortText(v));
        }
    }
    if (const Value* c = schema.find("const"); c && !jsonEqual(*c, v)) {
        return problem(path, "must be " + json::write(*c) + ", not " + shortText(v));
    }
    if (v.isNumber()) {
        if (auto st = checkNumber(schema, v, path); !st) {
            return st;
        }
    } else if (v.isString()) {
        if (auto st = checkString(schema, v, path); !st) {
            return st;
        }
    } else if (v.isArray()) {
        if (auto st = checkArray(schema, v, path, depth); !st) {
            return st;
        }
    } else if (v.isObject()) {
        if (auto st = checkObject(schema, v, path, depth); !st) {
            return st;
        }
    }
    if (const Value* any = schema.find("anyOf"); any && any->isArray() && !any->asArray().empty()) {
        std::optional<Error> first;
        bool firstWasType = false;
        bool ok = false;
        for (const Value& sub : any->asArray()) {
            auto st = check(sub, v, path, depth + 1);
            if (st) {
                ok = true;
                break;
            }
            // Report the alternative that got furthest: one whose type matched, if any did.
            const bool typeOnly = !st.error().context.empty() && st.error().context.back() == kTypeMismatch;
            if (!first || (firstWasType && !typeOnly)) {
                first = st.error();
                firstWasType = typeOnly;
            }
        }
        if (!ok) {
            return tl::unexpected<Error>(*first);
        }
    }
    if (const Value* one = schema.find("oneOf"); one && one->isArray() && !one->asArray().empty()) {
        int matches = 0;
        std::optional<Error> first;
        for (const Value& sub : one->asArray()) {
            auto st = check(sub, v, path, depth + 1);
            if (st) {
                ++matches;
            } else if (!first) {
                first = st.error();
            }
        }
        if (matches == 0) {
            return tl::unexpected<Error>(*first);
        }
        if (matches > 1) {
            return problem(path, "matches more than one of the allowed forms");
        }
    }
    return {};
}

Schema::Schema(std::unique_ptr<Impl> impl) : impl_(std::move(impl)) {}
Schema::~Schema() = default;

Result<std::shared_ptr<const Schema>> Schema::load(std::string_view schemaJson)
{
    auto parsed = json::parse(schemaJson);
    if (!parsed) {
        return tl::unexpected<Error>(parsed.error());
    }
    try {
        auto impl = std::make_unique<Impl>();
        impl->root = std::move(*parsed);
        if (auto st = impl->prepare(impl->root, std::string(), 0); !st) {
            return tl::unexpected<Error>(st.error());
        }
        return std::shared_ptr<const Schema>(new Schema(std::move(impl)));
    } catch (const std::exception& e) {
        return tl::unexpected<Error>(Error{ErrorCode::Internal, std::string("Cannot load a schema: ") + e.what(), {}});
    }
}

Status Schema::validate(const json::Value& instance) const
{
    try {
        auto st = impl_->check(impl_->root, instance, std::string(), 0);
        if (!st) {
            st.error().context.clear(); // only the internal type-mismatch tag lives there
        }
        return st;
    } catch (const std::exception& e) {
        return tl::unexpected<Error>(Error{ErrorCode::Internal, std::string("Schema check failed: ") + e.what(), {}});
    }
}

std::string_view builtinSchemaText(std::string_view name)
{
    for (std::size_t i = 0; i < kEmbeddedSchemaCount; ++i) {
        if (name == kEmbeddedSchemas[i].name) {
            return {reinterpret_cast<const char*>(kEmbeddedSchemas[i].data), kEmbeddedSchemas[i].size};
        }
    }
    return {};
}

const Schema& builtinSchema(std::string_view name)
{
    static std::mutex mutex;
    static std::map<std::string, std::shared_ptr<const Schema>, std::less<>> loaded;
    const std::lock_guard<std::mutex> lock(mutex);
    if (const auto it = loaded.find(name); it != loaded.end()) {
        return *it->second;
    }
    const std::string_view text = builtinSchemaText(name);
    auto schema =
        text.empty() ? Result<std::shared_ptr<const Schema>>(tl::unexpected<Error>(Error{})) : Schema::load(text);
    if (!schema) {
        std::terminate(); // a compiled-in schema that does not load is caught by the unit tests
    }
    return *loaded.emplace(std::string(name), std::move(*schema)).first->second;
}

} // namespace ray::lib::detail
